const coopAxes=[['🤝','Teamwork'],['🧠','Depth'],['📖','Story'],['🔄','Replayability'],['⚔️','Skill / combat']];
function assessmentHtml(g){let a=coopAssessments[g.name];if(!a)return '';let rows=coopAxes.map(([icon,label],i)=>'<div class="assessment-row"><span>'+label+'</span><div class="rating-track"><div class="rating-fill" style="width:'+(a.scores[i]*20)+'%"></div></div><strong>'+a.scores[i]+'/5</strong></div>').join('');return '<section class="modal-section assessment"><h3>The co-op fit</h3>'+rows+'<div class="assessment-copy"><b>If you liked</b><p>'+esc(a.similar)+'</p><b>Why it works</b><p>'+esc(a.why)+'</p><b>Worth knowing</b><p>'+esc(a.caution)+'</p></div></section>'}
function broaderAssessmentHtml(g){if(coopAssessments[g.name])return assessmentHtml(g);const e=editorial[g.name];if(!e||!e.caution&&!e.similar)return '';return '<section class="modal-section assessment"><h3>Co-op notes</h3>'+(e.similar?'<p><b>If you liked:</b> '+esc(e.similar)+'</p>':'')+(e.caution?'<p>'+esc(e.caution)+'</p>':'')+'</section>'}
const editorial={"Split Fiction":{"review":"Built around two-player coordination, inventive challenges and frequent changes in mechanics. The co-op itself is central rather than optional."},"Portal 2":{"review":"Its dedicated two-player campaign focuses on communication, experimentation and solving interconnected puzzles together."},"PlateUp!":{"review":"Combines time-pressure teamwork with strategic kitchen layout and restaurant upgrades; strong replayability if you enjoy optimisation."},"Core Keeper":{"review":"Exploration, crafting and boss encounters give both players plenty to do; progression is more open-ended than story-driven."},"Deep Rock Galactic":{"review":"Distinct classes and cooperative objectives encourage meaningful roles, positioning and team communication."},"Overcooked! 2":{"review":"Coordination and planning matter, but frantic execution may feel chaotic if you prefer measured teamwork."},"Stardew Valley":{"review":"Relaxed shared progression with farming, exploration and planning; combat is secondary."},"Grounded":{"review":"Survival exploration and shared base-building with an emphasis on preparation and combat."},"Unrailed!":{"review":"A fast-paced coordination challenge where both players have clear responsibilities."},"For the King":{"review":"Turn-based tabletop-inspired campaigns demand joint decisions about routes, resources and tactical fights.","similar":"Northgard · Kingdom Two Crowns","caution":"The dice-driven systems can be unforgiving."},"Tick Tock: A Tale for Two":{"review":"Two separate devices show different clues; you must talk through what you see to solve each puzzle.","similar":"It Takes Two","caution":"Requires a voice connection, but not a networked game session."},"The Past Within":{"review":"Two players explore different time periods and exchange clues to progress through the mystery.","similar":"It Takes Two","caution":"Shorter and exclusively puzzle-focused."},"Heave Ho":{"review":"Each player grips and swings through levels where timing and cooperation matter more than combat.","similar":"Rayman Legends","caution":"Primarily local multiplayer; remote play needs a workaround."},"Tools Up!":{"review":"Renovation tasks reward splitting responsibilities and planning around shared spaces.","similar":"PlateUp! · Ship of Fools","caution":"Time pressure can make it hectic."},"Astroneer":{"review":"Explore planets, manage oxygen and build automated logistics networks together.","similar":"Don't Starve Together · Kingdom Two Crowns","caution":"More sandbox progression than authored story."},"No Man's Sky":{"review":"Explore planets, construct bases and undertake missions alongside another player.","similar":"Don't Starve Together","caution":"Some objectives and progression remain individual."},"Palworld":{"review":"Creature collecting, shared bases and combat offer multiple ways to contribute.","similar":"Don't Starve Together","caution":"Check platform-specific multiplayer and cross-play."},"PowerWash Simulator":{"review":"Relaxed co-op tasks let both players steadily clean environments at their own pace.","similar":"Spiritfarer","caution":"Very repetitive by design, with little challenge."},"Ultimate Chicken Horse":{"review":"Build obstacles and race through them, balancing sabotage with platforming skill.","similar":"Rayman Legends","caution":"Competitive rather than cooperative."},"Tekken 8":{"review":"Deep one-on-one fighting with substantial execution and matchup learning.","similar":"Tekken 7","caution":"Versus game, not co-op."},"Street Fighter 6":{"review":"Technical versus combat rewards spacing, timing and learning characters.","similar":"Tekken 7","caution":"Versus game, not co-op."},"Just Shapes & Beats":{"review":"Dodge rhythm-synchronised hazards together, with both players actively participating.","similar":"Cuphead · Kingdom Hearts Melody of Memory","caution":"Fast and demanding, with little conventional combat."},"Guacamelee! 2":{"review":"Metroidvania exploration and skill-based platforming alongside colourful combat.","similar":"Rayman Legends · Streets of Rage 4","caution":"Check remote-play arrangements; co-op is local-focused."},"Disney Illusion Island":{"review":"Cooperative exploration emphasises movement, abilities and helping each other.","similar":"Rayman Legends","caution":"Less combat-focused and may be gentler than your favourites."}};
function coverUrl(g){let id=steamIds[g.name];return id?'https://shared.steamstatic.com/store_item_assets/steam/apps/'+id+'/header.jpg':''}
function statusSelect(g,key,label,options){return `<label>${label}<select onchange="quickSet(${g.id},'${key}',this.value)">${options.map(v=>`<option value="${esc(v)}" ${g[key]===v?'selected':''}>${esc(v==='Good suggestion'?'Saved for later':v)}</option>`).join('')}</select></label>`}
function openGame(id){
 const g=games.find(x=>x.id===id);if(!g)return;const m=editorial[g.name]||{},image=coverUrl(g),store=steamIds[g.name]?'https://store.steampowered.com/app/'+steamIds[g.name]+'/':null;
 window.activeGalleryGame=g.name;
 const shots=gameplayShots[g.name]||[];
 const gallery=shots.length?'<div class="gallery-strip">'+shots.map((item,i)=>`<figure class="shot" role="button" tabindex="0" onclick="openLightbox(${i})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openLightbox(${i})}" aria-label="Enlarge screenshot ${i+1}"><img loading="lazy" src="${item[0]}" alt="${esc(g.name)} gameplay" onerror="this.closest('figure').style.display='none'"><figcaption>${esc(item[2])}</figcaption></figure>`).join('')+'</div>':'<p class="gallery-placeholder">'+(store?`<a target="_blank" rel="noopener" href="${store}">View screenshots on Steam ↗</a>`:'No screenshots available yet.')+'</p>';
 const links=`${store?`<a class="store-link" target="_blank" rel="noopener" href="${store}">View on Steam ↗</a>`:''}<a target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(g.name+' gameplay no commentary')}">Gameplay ↗</a><a target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${encodeURIComponent(g.name+' gameplay screenshots')}">Screenshots ↗</a><a target="_blank" rel="noopener" href="https://www.metacritic.com/search/${encodeURIComponent(g.name)}/">Metacritic ↗</a><a target="_blank" rel="noopener" href="https://opencritic.com/search/${encodeURIComponent(g.name)}">OpenCritic ↗</a>`;
 $('gameDetails').innerHTML=`<div class="detail-topbar"><span>${esc(g.name)}</span><button class="icon-button" onclick="closeGame()" aria-label="Close game details">×</button></div>${image?`<img class="detail-hero" src="${image}" alt="${esc(g.name)} cover artwork" onerror="this.remove()">`:''}<div class="detail-body"><div class="detail-heading"><div><p class="card-genre">${esc(g.genre)}</p><h2>${esc(g.name)}</h2></div><span class="detail-fit">${g.score}<small>YOUR FIT</small></span></div><p class="detail-meta">${esc(g.mode)}<span>·</span>${esc(g.platforms.split(',').join(' · '))}${g.verified?'<span class="verified" title="Co-op mode verified">Mode checked</span>':''}${store?`<a class="store-shortcut" href="${store}" target="_blank" rel="noopener">Steam ↗</a>`:''}</p><p class="detail-note">${esc(g.note)}</p><div class="status-controls">${statusSelect(g,'playState','Play status',['Not played','Currently playing','Played'])}${statusSelect(g,'verdict','Our verdict',['Unrated','Good suggestion','Not sure',"Probably won't play",'Loved','Okay','Disliked'])}</div><section class="media-panel"><h3 class="gallery-label">Screenshots</h3><div id="gameArt" hidden></div>${gallery}</section>${broaderAssessmentHtml(g)}<details class="review-details"><summary>Reviews & sources</summary><div class="critic-row">${m.critic?`<span class="critic-score">${m.critic}</span><span class="muted">Metacritic · ${esc(m.source)}</span>`:'<span class="muted">No verified critic score yet.</span>'}</div>${m.review?`<p>${esc(m.review)}</p><p class="media-caption">Editorial summary · Scores vary by platform.</p>`:''}<div class="media-links">${links}</div></details><p class="detail-disclaimer">Check co-op support on your platform before buying.</p><button class="btn edit-detail" onclick="closeGame();editGame(${g.id})">Edit game & notes</button></div>`;
 $('gameDialog').showModal();$('gameDialog').scrollTop=0;loadSteamMedia(g.id);
}

function switchMedia(video){$('gameArt').hidden=video;let v=$('gameVideo');if(v){v.hidden=!video;let iframe=v.querySelector('iframe');if(video&&!iframe.src)iframe.src=iframe.dataset.src;if(!video)iframe.removeAttribute('src')}$('artTab').classList.toggle('active',!video);if($('videoTab'))$('videoTab').classList.toggle('active',video)}
function closeGame(){let v=$('gameVideo');if(v){let f=v.querySelector('iframe');f.removeAttribute('src')}$('gameDialog').close()}

let lightboxIndex=0;let lightboxTouchStart=0;
function openLightbox(index){let shots=gameplayShots[window.activeGalleryGame]||[];if(!shots.length)return;lightboxIndex=index;updateLightbox();window.gameDialogScroll=$('gameDialog').scrollTop;$('gameDialog').close();$('lightbox').showModal();document.body.style.overflow='hidden'}
function updateLightbox(){let shots=gameplayShots[window.activeGalleryGame]||[];if(!shots.length)return;lightboxIndex=(lightboxIndex+shots.length)%shots.length;let shot=shots[lightboxIndex];$('lightboxImage').src=shot[0];$('lightboxImage').alt=window.activeGalleryGame+' — '+shot[1];$('lightboxCaption').textContent=shot[1]+' · '+shot[2];$('lightboxCount').textContent=window.activeGalleryGame+' · '+(lightboxIndex+1)+' of '+shots.length}
function moveLightbox(delta){lightboxIndex+=delta;updateLightbox()}
function closeLightbox(){if($('lightbox').open)$('lightbox').close();$('lightboxImage').removeAttribute('src');$('gameDialog').showModal();$('gameDialog').scrollTop=window.gameDialogScroll||0;document.body.style.overflow=''}
$('lightbox').addEventListener('cancel',e=>{e.preventDefault();closeLightbox()});
document.addEventListener('keydown',e=>{if(!$('lightbox').open)return;if(e.key==='ArrowLeft')moveLightbox(-1);if(e.key==='ArrowRight')moveLightbox(1)});
document.addEventListener('touchstart',e=>{if($('lightbox').open)lightboxTouchStart=e.changedTouches[0].screenX},{passive:true});
document.addEventListener('touchend',e=>{if(!$('lightbox').open)return;let d=e.changedTouches[0].screenX-lightboxTouchStart;if(Math.abs(d)>55)moveLightbox(d>0?-1:1)},{passive:true});

const steamCache=new Map();
async function getSteamDetails(appid){
 if(steamCache.has(appid))return steamCache.get(appid);
 const key='coopAtlasSteamV1_'+appid;
 try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved&&Date.now()-saved.time<86400000){steamCache.set(appid,saved.data);return saved.data}}catch(e){}
 // Steam's store endpoint has no browser CORS header; the proxy is only used for public game metadata.
 const url='https://store.steampowered.com/api/appdetails?appids='+appid+'&l=english';
 const response=await fetch('https://proxy.cors.dev/'+url,{signal:AbortSignal.timeout(12000),credentials:'omit'});
 if(!response.ok)throw Error('Media service unavailable');
 const json=await response.json(),entry=json[String(appid)];
 if(!entry||!entry.success||!entry.data)throw Error('No store data');
 const data=entry.data;steamCache.set(appid,data);
 try{sessionStorage.setItem(key,JSON.stringify({time:Date.now(),data:{screenshots:data.screenshots,metacritic:data.metacritic,name:data.name}}))}catch(e){}
 return data;
}
async function loadSteamMedia(id){
 const g=games.find(x=>x.id===id);if(!g||!steamIds[g.name])return;
 const gameName=g.name,appid=steamIds[gameName];
 const section=$('gameArt')?.parentElement;
 if(!section)return;
 let existing=section.querySelector('.steam-load');
 if(!existing){existing=document.createElement('p');existing.className='media-caption steam-load';existing.textContent='Loading screenshots…';section.appendChild(existing)}
 try{
  const data=await getSteamDetails(appid);
  if(!$('gameDialog').open||window.activeGalleryGame!==gameName)return;
  const fresh=(data.screenshots||[]).filter(x=>x.path_full&&x.path_full.startsWith('https://')).slice(0,8).map((x,i)=>[x.path_full,'Official gameplay screenshot '+(i+1),'Steam store']);
  if(fresh.length){
   gameplayShots[gameName]=fresh;
   const gallery=section.querySelector('.gallery-strip'),placeholder=section.querySelector('.gallery-placeholder');
   if(gallery)gallery.remove();if(placeholder)placeholder.remove();
   const label=section.querySelector('.gallery-label');if(label)label.textContent='Screenshots';
   const strip=document.createElement('div');strip.className='gallery-strip';
   fresh.forEach((item,i)=>{const fig=document.createElement('figure');fig.className='shot';fig.tabIndex=0;fig.setAttribute('role','button');fig.setAttribute('aria-label','Enlarge screenshot '+(i+1));fig.onclick=()=>openLightbox(i);fig.onkeydown=e=>{if(e.key==='Enter')openLightbox(i)};const img=document.createElement('img');img.src=item[0];img.loading='lazy';img.alt=gameName+' '+item[1];img.onerror=()=>{fig.style.display='none'};const cap=document.createElement('figcaption');cap.textContent=item[1]+' · Steam store';fig.append(img,cap);strip.appendChild(fig)});
   const caption=document.createElement('p');caption.className='media-caption';caption.textContent='Steam store · Tap to enlarge';section.append(strip,caption);
  }
  if(data.metacritic&&Number.isFinite(data.metacritic.score)){
   const row=$('gameDetails').querySelector('.critic-row');
   if(row){const old=row.querySelector('.steam-critic');if(old)old.remove();const el=document.createElement('div');el.className='steam-critic';const score=document.createElement('span');score.className='critic-score';score.textContent=data.metacritic.score;const label=document.createElement('span');label.className='muted';label.textContent=' Metacritic · Steam-listed PC score ';el.append(score,label);if(data.metacritic.url){const a=document.createElement('a');a.href=data.metacritic.url;a.target='_blank';a.rel='noopener';a.textContent='Source ↗';el.appendChild(a)}row.appendChild(el);const missing=[...row.querySelectorAll('span.muted')].find(x=>x.textContent.includes('Critic score not yet verified'));if(missing)missing.remove()}
  }
  existing.textContent='';existing.hidden=true;
 }catch(e){if(existing)existing.textContent='More screenshots unavailable.'}
}

render();
